func assetSlices(assets []AssetShare) []chart.Slice {
	out := make([]chart.Slice, len(assets))
	for i, a := range assets {
		out[i] = chart.Slice{Label: a.Symbol, Value: a.Volume, Color: a.Color}
	}
	return out
}

